interface {{ port.name }}
{% if port.mode == "access" %}
 switchport access vlan {{ port.vlan }}
{% elif port.mode == "trunk" and port.vlans is defined %}
 switchport mode trunk
 switchport trunk allowed vlan {{ port.vlans }}
{% else %}
 shutdown
{% endif %}

{% set ns = namespace(access=0) %}
{% for p in ports %}
{% if p.mode == "access" %}{% set ns.access = ns.access + 1 %}{% endif %}
{% endfor %}
! access ports: {{ ns.access }}

@mcp.prompt()
def troubleshoot_interface(device: str, interface: str) -> str:
    """Guide troubleshooting of one interface."""
    # Purpose: build a reusable troubleshooting request
    return (f"Check {interface} on {device}: read its status and errors, "
            f"compare it with its neighbor, and suggest next steps.")
